import org.junit.Test;
import static org.junit.Assert.*;

public class OnlineStockSpanTest {

    @Test
    public void nextEmptyListTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(100);
        assertEquals("Span for first element should be 1", 1, result);
    }

    @Test
    public void nextPriceGreaterThanAllTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = new int[]{90, 95, 98};
        for(int price: prices) {
            onlineStockSpan.next(price);
        }
        int result = onlineStockSpan.next(100);
        assertEquals("Span for price greater than all previous should be equal to count of all previous", 4, result);
    }

    @Test
    public void nextPriceLessThanPreviousTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = new int[]{90, 95, 99};
        for(int price: prices) {
            onlineStockSpan.next(price);
        }
        int result = onlineStockSpan.next(94);
        assertEquals("Span for price less than previous should be 1", 1, result);
    }

    @Test
    public void nextPriceEqualToPreviousTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = new int[]{90, 95, 99};
        for(int price: prices) {
            onlineStockSpan.next(price);
        }
        int result = onlineStockSpan.next(99);
        assertEquals("Span for price equal to previous should be count of all equal or less", 2, result);
    }

    @Test
    public void calculateSpansEmptyListTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = new int[]{};
        int[] result = onlineStockSpan.calculateSpans(prices);
        assertEquals("Span array for empty prices should be empty", 0, result.length);
    }

    @Test
    public void calculateSpansSingleElementTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = new int[]{90};
        int[] result = onlineStockSpan.calculateSpans(prices);
        assertEquals("Span array for single value prices should have length 1", 1, result.length);
        assertEquals("Span of single value prices should be 1", 1, result[0]);
    }

    @Test
    public void calculateSpansMultipleElementsTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = new int[]{90, 95, 92, 100};
        int[] expected = new int[]{1, 2, 1, 4};
        int[] result = onlineStockSpan.calculateSpans(prices);
        assertArrayEquals("Span array different from expected", expected, result);
    }
}
